102	        let order_column = order_by.field.as_column(ctx);
103	        let order_definition: OrderDefinition = match order_by.sort_aggregation {
104	            SortAggregation::Count => (count(order_column.clone()).into(), order),
105	            SortAggregation::Avg => (avg(order_column.clone()).into(), order),
106	            SortAggregation::Sum => (sum(order_column.clone()).into(), order),
107	            SortAggregation::Min => (min(order_column.clone()).into(), order),
108	            SortAggregation::Max => (max(order_column.clone()).into(), order),
109	        };
110	
111	        OrderByDefinition {
112	            order_column: order_column.into(),
113	            order_definition,
114	            joins: vec![],
