1	use crate::{
2	    model_extensions::{AsColumns, AsTable, ColumnIterator},
3	    Context,
4	};
5	use quaint::{ast::Table, prelude::Column};
6	use query_structure::{walkers, ModelProjection, Relation, RelationField};
7	
8	pub(crate) trait RelationFieldExt {
9	    fn m2m_columns(&self, ctx: &Context<'_>) -> Vec<Column<'static>>;
10	    fn join_columns(&self, ctx: &Context<'_>) -> ColumnIterator;
11	    fn identifier_columns(&self, ctx: &Context<'_>) -> ColumnIterator;
12	    fn as_table(&self, ctx: &Context<'_>) -> Table<'static>;
13	}
14	
15	impl RelationFieldExt for RelationField {
16	    fn m2m_columns(&self, ctx: &Context<'_>) -> Vec<Column<'static>> {
17	        let is_side_a = self.walker().relation().relation_fields().next().map(|rf| rf.id) == Some(self.id);
18	        let prefix = if is_side_a { "B" } else { "A" };
19	        vec![Column::from(prefix).table(self.as_table(ctx))]
20	    }
21	
22	    fn join_columns(&self, ctx: &Context<'_>) -> ColumnIterator {
23	        let relation = self.walker().relation();
24	        match relation.refine() {
25	            walkers::RefinedRelationWalker::ImplicitManyToMany(m) => {
26	                let is_side_a = relation.relation_fields().next().map(|rf| rf.id) == Some(self.id);
27	                let column_name = if is_side_a {
28	                    m.column_b_name()
29	                } else {
30	                    m.column_a_name()
31	                };
32	                ColumnIterator::from(vec![column_name.into()])
33	            }
34	            _ => ModelProjection::from(self.linking_fields()).as_columns(ctx),
35	        }
36	    }
37	
38	    fn identifier_columns(&self, ctx: &Context<'_>) -> ColumnIterator {
39	        let relation = self.walker().relation();
40	        match relation.refine() {
41	            walkers::RefinedRelationWalker::ImplicitManyToMany(m) => {
42	                let is_side_a = relation.relation_fields().next().map(|rf| rf.id) == Some(self.id);
43	                let column_name = if is_side_a {
44	                    m.column_a_name()
45	                } else {
46	                    m.column_b_name()
47	                };
48	                ColumnIterator::from(vec![column_name.into()])
49	            }
50	            _ => ModelProjection::from(self.model().primary_identifier()).as_columns(ctx),
51	        }
52	    }
53	
54	    fn as_table(&self, ctx: &Context<'_>) -> Table<'static> {
55	        if self.relation().is_many_to_many() {
56	            self.related_field().relation().as_table(ctx)
57	        } else {
58	            self.model().as_table(ctx)
59	        }
60	    }
61	}
62	
63	impl AsTable for Relation {
64	    /// The `Table` with the foreign keys are written. Can either be:
65	    ///
66	    /// - A separate table for many-to-many relations.
67	    /// - One of the model tables for one-to-many or one-to-one relations.
68	    /// - A separate relation table for all relations, if using the deprecated
69	    ///   data model syntax.
70	    fn as_table(&self, ctx: &Context<'_>) -> Table<'static> {
71	        match self.walker().refine() {
72	            // In this case we must define our unique indices for the relation
73	            // table, so MSSQL can convert the `INSERT .. ON CONFLICT IGNORE` into
74	            // a `MERGE` statement.
75	            walkers::RefinedRelationWalker::ImplicitManyToMany(ref m) => {
76	                let model_a = m.model_a();
77	                let prefix = model_a.schema_name().unwrap_or_else(|| ctx.schema_name()).to_owned();
78	                let table: Table = (prefix, m.table_name().to_string()).into();
79	
80	                table.add_unique_index(vec![Column::from("A"), Column::from("B")])
81	            }
82	            walkers::RefinedRelationWalker::Inline(ref m) => {
83	                self.dm.find_model_by_id(m.referencing_model().id).as_table(ctx)
84	            }
85	            walkers::RefinedRelationWalker::TwoWayEmbeddedManyToMany(_) => {
86	                unreachable!("TwoWayEmbeddedManyToMany relation in sql-query-connector")
87	            }
88	        }
89	    }
90	}
