///     ON (<m2m_alias>.<parent_ref> = <Parent | previous_join_alias>.<parent_id>)
/// LEFT JOIN Child AS <alias>
///     ON (<alias>.<child_id> = <m2m_alias>.<child_ref>)
/// ```
///
/// The returned vector is ordered so that the join table join comes first and the related model
/// join comes second. The alias of the last join (the related model) is the one to be used as the
/// parent alias of the next hop.
pub(crate) fn compute_m2m_join(
    field: &RelationFieldRef,
    alias: &str,
    m2m_alias: &str,
    parent_alias: Option<&str>,
    ctx: &Context<'_>,
) -> Vec<AliasedJoin> {
    // The join table (_ParentToChild).
    let m2m_table = field.as_table(ctx).alias(m2m_alias.to_owned());
    // Parent primary identifiers.
    let parent_ids = ModelProjection::from(field.model().primary_identifier());
    // Columns on the join table referencing the parent.
    let parent_ref_columns = field.related_field().m2m_columns(ctx);

    // <m2m_alias>.<parent_ref> = <Parent | previous_join_alias>.<parent_id>
    let m2m_on_conditions: Vec<Expression> = parent_ref_columns
        .into_iter()
        .zip(parent_ids.as_columns(ctx))
        .map(|(m2m_col, parent_col)| {
            let left = Column::from((m2m_alias.to_owned(), m2m_col.name.to_string()));
